scwin.vInitTpCd = '0';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 기관 데이터를 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_INST_INFO";
    url += "&queryId=lds.stf.bnscommon.select.listInstCd";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_INST_NM=" + $c.stf.getObjectValue(txb_InstNm);
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/********************************************** 
 * 함수명   : fn_InitInstInfo
 * 설명       : 기관 데이터를 조회한다.
 ***********************************************/
scwin.fn_InitInstInfo = function() {
    dts_List.removeAll();
    grd_List.Redraw = false;
    var initTpCd = $c.stf.getObjectValue(txb_InitTpCd);
    //대표주관회사
    if (initTpCd == '1') {
        scwin.fn_SetRepMajagntCom();
    }
    //보증기관
    else if (initTpCd == '2') {
        scwin.fn_SetGuarInst();
    }
    //등록기관
    else if (initTpCd == '3') {
        scwin.fn_SetRegnst();
    }
    //원리금지급대행기관
    else if (initTpCd == '4') {
        scwin.fn_SetPrincintPayAgnt();
    }
    //수탁기관
    else if (initTpCd == '5') {
        scwin.fn_SetTrstInst();
    }
    grd_List.Redraw = true;
};



