/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        fn_GetPar = prt.fn_GetPar;
        fn_SetPar = prt.fn_SetPar;
    }
    if (fn_GetPar != undefined) {
        var arrPar = new Array();
        fn_GetPar(arrPar);
        if (typeof(arrPar[0].LBL_NM != 'undefined') &&
            arrPar[0].LBL_NM != '') {
            $c.stf.setObjectValue(txb_LblNm, arrPar[0].LBL_NM);
        }
        //0:조회, 1:대표주관회사, 2:보증기관, 3:등록기관, 4:원리금지급대행기관, 5:수탁기관/사채관리회사
        if (typeof(arrPar[0].INIT_TP_CD != 'undefined')) {
            $c.stf.setObjectValue(txb_InitTpCd, arrPar[0].INIT_TP_CD);
        } else {
            $c.stf.setObjectValue(txb_InitTpCd, '0');
            $c.stf.setObjectValue(txb_InstNm, arrPar[0].INST_CD);
            scwin.fn_Search();
        }
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.txb_InstNm_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_Search();
};
scwin.gform_onload = function() {
    //숨김처리
    $c.stf.showObj(txb_InitTpCd, false);
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(panel_1);
    //파라미터설정
    scwin.fn_SetParam();

    //목록조회
    /*
    dts_List.SyncLoad = true;
    dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_INST_INFO";
    dts_List.Reset();
    dts_List.SyncLoad = false;
    */

    //초기기관정보설정
    if ($c.stf.getObjectValue(txb_InitTpCd) != '') {
        scwin.fn_InitInstInfo();
        return;
    }
    //fn_Search();

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    if (row > 0) {
        if (dts_List.getCellData(row, "INST_STAT_CD") != '1') {
            $c.win.alert('기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.');
            return;
        }
        var arrPar = new Array();
        arrPar[0] = {
            INST_CD: dts_List.getCellData(row, "INST_CD"),
            INST_NM: dts_List.getCellData(row, "INST_NM")
        };
        fn_SetPar(arrPar);
        await $c.frame.CloseFrame();
    }
};
scwin.btn_init_onclick = function() {
    scwin.fn_InitInstInfo();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
